pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        address[] memory tos = new address[](2);
        tos[0] = address(0x1111);
        tos[1] = address(0x2222);
        uint[] memory v = new uint[](2);
        v[0] = 1;
        v[1] = 100;
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        c.transfer(tos, v);
        uint overflowVal = type(uint).max / 1000000000000000000 + 1;
        address[] memory tos2 = new address[](2);
        tos2[0] = address(0x1111);
        tos2[1] = address(0x2222);
        uint[] memory v2 = new uint[](2);
        v2[0] = 1;
        v2[1] = overflowVal;
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok;
        try c.transfer(tos2, v2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Reference does not revert, but should have reverted due to overflow");
    }
}
